// From the library's documentation
std::vector<Stem> run(Model& m, const AudioBuffer& chunk) {
  auto input = toTensor(chunk);          // samples → model input
  auto output = m.forward(input);        // vocals, drums, bass, other
  return toStems(output, chunk.sampleRate);
}

// Your idea: "Work through the song in 10-second pieces"
for (int start = 0; start < song.length(); start += 10 * song.sampleRate) {
  auto stems = run(model, song.slice(start, 10 * song.sampleRate));
  append(result, stems);
  progress(start / (float) song.length());
}
